$('forgot').onclick=()=>action(()=>modal('找回密码',[{name:'email',label:'账号邮箱',type:'email',value:$('email').value}],async b=>{await api('security/forgot',b);message('如果账号存在，会收到找回链接；测试环境请联系管理员查看测试邮件。');}));
async function publicShop(){try{const d=await api('public/commerce');commerceEnabled=!!d.enabled;$('invite-wrap').hidden=!d.invite_only;const c=$('public-shop');c.hidden=!d.enabled||!!me;if(!d.enabled)return;c.replaceChildren(element('h2',d.test_mode?'获邀试运营 · 测试购买':'选择适合你的套餐'),helpNote(d.test_mode?'当前不会实际扣款。测试权益仅适用于测试节点。':'登录后创建订单，前往安全收银台付款。'),table(['套餐','周期','金额','额度','设备'],d.plans.map(p=>[p.name,p.kind==='traffic'?'当前有效周期':p.days+' 天',(p.price_cents/100).toFixed(2)+' '+(p.currency||'cny').toUpperCase(),p.traffic_bytes?bytes(p.traffic_bytes):'不限',p.kind==='traffic'?'沿当前套餐':p.devices])));clientDownload(c,d.release);for(const [label,key]of [['服务说明','terms'],['隐私说明','privacy'],['退款说明','refund_policy']]){const details=element('details'),summary=element('summary',label);details.append(summary,element('p',d[key]||'正式政策尚待经营方确认。'));c.append(details);}}catch(e){message(e);}}
async function securityFragment(){if(location.hash==='#security'){await openSecurity();return;}const params=new URLSearchParams(location.hash.slice(1));if(params.has('invite')){$('invite').value=params.get('invite');$('invite-wrap').hidden=false;history.replaceState(null,'',location.pathname);return;}if(params.has('verify')){const token=params.get('verify');history.replaceState(null,'',location.pathname);try{await api('security/verify',{token});message('邮箱验证成功，请登录后继续购买。');if(me)await refreshIdentity();}catch(e){message(e);}}if(params.has('reset')){const token=params.get('reset');history.replaceState(null,'',location.pathname);modal('设置新密码',[{name:'password',label:'新密码（至少 12 字节）',type:'password',minlength:12,maxlength:256}],async b=>{await api('security/reset',{token,password:b.password});resetAuth('密码已重置，请重新登录。');});}}
publicShop();initialIdentityReady.then(securityFragment).catch(message);
window.addEventListener('hashchange',()=>{const fragment=new URLSearchParams(location.hash.slice(1));if(['invite','verify','reset'].some(key=>fragment.has(key)))initialIdentityReady.then(securityFragment).catch(message);});
setInterval(()=>{if(me&&(view==='operations'||commerceEnabled&&['orders','billing','payments'].includes(view))&&!actionBusy&&!saving&&!$('dialog').open&&!document.activeElement?.matches('input,textarea,select'))render().catch(message);},15000);
